package com.yuegang.zhihui.knowledge.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.knowledge.security.*;import jakarta.servlet.http.*;import java.nio.charset.*;import java.nio.file.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.jdbc.core.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/knowledge/documents")public final class KnowledgeDownloadController{private final JdbcTemplate jdbc;private final KnowledgeUserResolver users;private final Path root;public KnowledgeDownloadController(DataSource d,KnowledgeUserResolver u,@Value("${ygh.knowledge.storage-root}")String r){jdbc=new JdbcTemplate(d);users=u;root=Path.of(r).toAbsolutePath().normalize();}@GetMapping("/{id}/content")ResponseEntity<Resource>content(@PathVariable String id,@RequestParam(defaultValue="true")boolean inline,HttpServletRequest r){long document=positive(id);var row=jdbc.query("SELECT file_name,media_type,storage_key,size_bytes,status FROM knowledge_document WHERE id=?",x->{if(!x.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new Row(x.getString(1),x.getString(2),x.getString(3),x.getLong(4),x.getString(5));},document);users.resolve(r,!"PUBLISHED".equals(row.status));Path file=root.resolve(row.key).normalize();if(!file.startsWith(root)||!Files.isRegularFile(file))throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);Resource resource=new FileSystemResource(file);ContentDisposition disposition=(inline?ContentDisposition.inline():ContentDisposition.attachment()).filename(row.name,StandardCharsets.UTF_8).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(row.media)).contentLength(row.size).header(HttpHeaders.CONTENT_DISPOSITION,disposition.toString()).header("X-Content-Type-Options","nosniff").body(resource);}private record Row(String name,String media,String key,long size,String status){}private static long positive(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
